agI(a){return"\u0644\u0646\u0631\u062a\u0642\u0650 \u0628\u0645\u0646\u0634\u0623\u0629 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u062f\u0631\u062c\u0629 \u0648\u0627\u062d\u062f\u0629. \u0627\u0644\u0645\u0633 **"+a+"**."},
